-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_deadline_guarded_transfer(p_transfer_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_transfer_id AND procedure = 'deadline_guarded_transfer' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('deadline_guarded_transfer', p_transfer_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_deadline_guarded_transfer(p_transfer_id text, p_payer text, p_payee text, p_amount bigint, p_currency text, p_now text, p_deadline text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    -- (no computed values)
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_transfer_id AND procedure = 'deadline_guarded_transfer' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_transfer_id AND procedure = 'deadline_guarded_transfer' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_transfer_id, 'deadline_guarded_transfer')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;


    -- debit payer_out (payer.wallet) when p_now >= p_deadline
    IF p_now >= p_deadline THEN
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for payer_out';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('payer.wallet', p_payer, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('deadline_guarded_transfer', 'payer_out', 'payer.wallet', p_payer, p_amount, p_currency, -(p_amount), p_transfer_id);
    END IF;

    -- credit payee_in (payee.wallet) when p_now >= p_deadline
    IF p_now >= p_deadline THEN
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for payee_in';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('payee.wallet', p_payee, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('deadline_guarded_transfer', 'payee_in', 'payee.wallet', p_payee, p_amount, p_currency, p_amount, p_transfer_id);
    END IF;

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'deadline_guarded_transfer' AND idempotency_key = p_transfer_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_transfer_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('deadline_guarded_transfer', p_transfer_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
